// Test-only deterministic fixtures. Reference outputs are generated by the named external engine.
import {rng} from '../apps/web/public/dsiq/worker.mjs';
import {AffineClifford} from '../apps/web/public/dsiq/affine.mjs';
import {contractAmplitude} from '../apps/web/public/dsiq/contraction.mjs';
const mode=process.argv[2];const r=rng(873609),n=100,gs=[],gate=(name,q,controls=[],theta)=>({name,q,controls,...(theta===undefined?{}:{theta})});
if(mode==='stim'){
 const d=new AffineClifford(n);const paulis=[];
 for(let j=0;j<10000;j++){const q=Math.floor(r()*n),c=(q+1+Math.floor(r()*(n-1)))%n,name=['h','x','y','z','s','sdg','cx','cy','cz','swap'][Math.floor(r()*10)],g=gate(name,q,['cx','cy','cz','swap'].includes(name)?[c]:[]);gs.push(g);d.apply(g)}
 // A complete set of stabilizer witnesses obtained by conjugating Z generators
 // under the unchanged circuit (independent symplectic implementation in frame).
 // Additional random Pauli strings and generated basis samples detect errors.
 const {compileFrame}=await import('../apps/web/public/dsiq/frame-factor.mjs');
 const inverse=gs.slice().reverse().map(g=>({...g,name:g.name==='s'?'sdg':g.name==='sdg'?'s':g.name})),p=compileFrame(n,inverse),parity=a=>{let k=0;while(a){a&=a-1n;k^=1}return k};
 for(const g of p.Z){let s='',ys=0;for(let q=n-1;q>=0;q--){const x=Number((g.x>>BigInt(q))&1n),z=Number((g.z>>BigInt(q))&1n);ys+=x&&z?1:0;s+='IXZY'[x+2*z]}const exponent=((g.p-ys)%4+4)%4;if(exponent%2)throw Error('Non-Hermitian generator');const sign=exponent===2?-1:1;const actual=d.expectation(s);if(sign!==actual)throw Error('Internal stabilizer mismatch');paulis.push({s,value:actual})}
 for(let j=0;j<1000;j++){const s=Array.from({length:n},()=> 'IXYZ'[Math.floor(r()*4)]).join('');paulis.push({s,value:d.expectation(s)})}
 console.log(JSON.stringify({n,gates:gs,paulis,rank:d.r,norm:d.norm(),stabilizerWitnesses:100}));
}else if(mode==='quimb'){
 for(let q=0;q<n;q++)gs.push(gate('ry',q,[],.4+r()),gate('rz',q,[],r()*2-1));
 // 10x10 two low-depth disjoint CZ rounds in each orientation.
 for(let j=0;j<2;j++)for(let row=0;row<10;row++)for(let col=j;col<9;col+=2)gs.push(gate('cz',row*10+col+1,[row*10+col]));
 for(let q=0;q<n;q++)gs.push(gate('rx',q,[],.2*r()));
 for(let j=0;j<2;j++)for(let row=j;row<9;row+=2)for(let col=0;col<10;col++)gs.push(gate('cz',(row+1)*10+col,[row*10+col]));
 const queries=[];for(let i=0;i<16;i++){const bits=Array.from({length:n},()=>r()<.5?'0':'1').join('');const a=contractAmplitude(n,gs,bits,{maxBytes:134217728,maxWork:500000000,maxVariables:10000,ordering:'pair'});queries.push({bits,real:a.real,imag:a.imag,log2Magnitude:a.log2Magnitude})}
 console.log(JSON.stringify({n,gates:gs,queries}));
}else throw Error('Select stim or quimb');
